                options.Path,
                options.Base,
                options.Head,
                options.Branch,
                options.Last);
            var results = await new ChangeSetReviewService().ReviewAsync(
                new GitMergeRangeChangeSetProvider(),
                query,
                new ChangeReviewOptions(!options.NoWrite, reviewer),
                cancellationToken).ConfigureAwait(false);
